using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using RentalCamera.Data;
namespace RentalCamera.Controllers; public class BaoTriController:BaseController{private readonly RentalCameraDbContext _db;public BaoTriController(RentalCameraDbContext db)=>_db=db;public async Task<IActionResult> Index(){ViewBag.AllDevices=await _db.ThietBi.Include(x=>x.DongMay).OrderBy(x=>x.MaThietBi).ToListAsync();return View(await _db.ThietBi.Include(x=>x.DongMay).Where(x=>x.TrangThai=="BAO_TRI"||x.TrangThai=="HONG").ToListAsync());}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>SetStatus(string id,string status,string? tinhTrang){var x=await _db.ThietBi.FindAsync(id);if(x==null)return NotFound();if(!new[]{"BAO_TRI","HONG","SAN_SANG","NGUNG_KINH_DOANH"}.Contains(status)){TempData["Error"]="Trạng thái không hợp lệ.";return RedirectToAction("Index");}x.TrangThai=status;if(!string.IsNullOrWhiteSpace(tinhTrang))x.TinhTrang=tinhTrang;await _db.SaveChangesAsync();TempData["Ok"]="Đã cập nhật tình trạng bảo trì.";return RedirectToAction("Index");}}
